export const customerAddScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}): string => `<script>
// Live-warning JS hint — the REAL enforcement is server-side (see the PHP block/warn handling
// above); this only gives the operator an early heads-up before they submit, using the same
// centralized policy via customers_check_mobile.php?mobile=...&name=....
(function () {
  var input = document.getElementById('mobileInput');
  var nameInput = document.querySelector('input[name="full_name"]');
  var warn = document.getElementById('mobileWarning');
  if (!input) return;
  function check() {
    var mobile = input.value.trim();
    var name = nameInput ? nameInput.value.trim() : '';
    if (mobile.length < 7) { warn.classList.add('d-none'); return; }
    fetch('${h(u('api/customers_check_mobile.php'))}?mobile=' + encodeURIComponent(mobile) + '&name=' + encodeURIComponent(name))
      .then(function (r) { return r.json(); })
      .then(function (data) {
        if (data.action === 'allow') { warn.classList.add('d-none'); return; }
        var names = (data.matches || []).map(function (m) { return m.full_name + ' (' + m.customer_code + ')'; }).join(', ');
        if (data.action === 'block') {
          warn.className = 'form-text text-danger';
          warn.textContent = 'This mobile number is already registered for ' + names + '. Please use the existing customer instead — or check the confirmation box after saving if this is genuinely a different person.';
        } else {
          warn.className = 'form-text text-warning';
          warn.textContent = 'Note: this mobile number is already used by: ' + names + '. You can still save if this is a different customer (e.g. a shared family number).';
        }
        warn.classList.remove('d-none');
      })
      .catch(function () { /* fail silently — this is a soft UX hint, server-side still enforces the real rule */ });
  }
  input.addEventListener('blur', check);
  if (nameInput) nameInput.addEventListener('blur', check);
})();
</script>`;
