export const customerViewScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}): string => `<script>
document.getElementById('sendDueReminderBtn').addEventListener('click', function () {
  const btn = this;
  const originalText = btn.textContent;
  btn.disabled = true; btn.textContent = 'Sending...';
  const formData = new FormData();
  formData.append('customer_id', ${a.id});
  formData.append('csrf_token', ${j(a.csrf)});
  fetch('${h(u('api/whatsapp_send_due_reminder.php'))}', { method: 'POST', body: formData })
    .then(r => r.json())
    .then(function (result) {
      btn.disabled = false; btn.textContent = originalText;
      if (result.success) {
        alert(result.duplicate ? 'A reminder was already sent today.' : 'Due reminder queued for sending.');
      } else {
        alert('Could not send: ' + (result.error || 'Unknown error.'));
      }
    })
    .catch(function () {
      btn.disabled = false; btn.textContent = originalText;
      alert('Could not reach the server. Please try again.');
    });
});
</script>`;
